// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.detectionimport timber.log.Timberimport com.roshan.persona.vision.ocr.BoundingBoximport com.roshan.persona.vision.ocr.RgbImageimport kotlinx.coroutines.CoroutineDispatcherimport kotlinx.coroutines.withContext/** * NOUS — Object Detector (Module 6 v4 — Step 6.3). * * Wraps the SSD MobileNetV3 model (INT8 quantized, 6 MB) for real-time object * detection via NNAPI delegate (Qualcomm QNN / MediaTek NeuroPilot). * * ## Performance (per strategy v4) * * | Device | Backend | FPS (motion-gated) | Latency per frame | * |--------|---------|-------------------|-------------------| * | Pixel 8 Pro (SD 8 Gen 3) | QNN | 30 FPS | 33 ms | * | Redmi Note 13 (SD 7 Gen 1) | QNN | 25 FPS | 40 ms | * | Realme Narzo 60 (Dimensity 7050) | NeuroPilot | 20 FPS | 50 ms | * | Redmi 12 (Helio G99) | NeuroPilot + OpenCL | 15 FPS | 65 ms | * | Redmi 12C (Helio G85) | XNNPACK | 8-12 FPS | 80-120 ms | * * ## Classes (per strategy v4 §"DetectionClass") * * 80 COCO classes (person, car, dog, etc.) + 8 NOUS India extensions * (auto-rickshaw, cow, plant, medicine bottle, currency note, receipt, * prescription, food plate). * * ## Confidence Thresholds (per strategy v4 §"Issue 1") * *  - ≥ 0.50 → display (bounding box on UI) *  - ≥ 0.70 → speak (TTS announces label) *  - < 0.50 → suppress (filtered out by NMS post-processor) * * ## Non-Maximum Suppression (NMS) * * SSD outputs multiple overlapping boxes for the same object. NMS filters * them by: *  1. Sort by confidence descending. *  2. Keep the highest-confidence box. *  3. Remove all boxes with IoU > 0.45 (Intersection over Union) with the kept box. *  4. Repeat for next-highest remaining box. * * ## Testability * * Native SSD inference is abstracted via [SsdModelDelegate] interface. * Production: [TfLiteSsdDelegate] wraps TFLite + NNAPI delegate. * Tests: [FakeSsdDelegate] returns canned detections. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Step 6.3: ObjectDetectionEngine</a> */class ObjectDetector(    private val delegate: SsdModelDelegate,    private val nmsIoUThreshold: Float = DEFAULT_NMS_IOU_THRESHOLD,    private val minConfidence: Float = DEFAULT_MIN_CONFIDENCE,    private val dispatcher: CoroutineDispatcher,) {    /**     * Detect objects in [frame].     *     * @param frame the input frame (RGB).     * @return list of detected objects (NMS-filtered, confidence-sorted).     */    suspend fun detect(frame: RgbImage): List<DetectedObject> = withContext(dispatcher) {        if (!delegate.isReady()) {            Timber.tag(TAG).w("SSD model not ready — returning empty detections.")            return@withContext emptyList()        }        val startTime = System.currentTimeMillis()        val rawDetections = try {            delegate.detect(frame)        } catch (t: Throwable) {            Timber.tag(TAG).e("SSD inference failed", t)            return@withContext emptyList()        }        // Filter by minimum confidence.        val filtered = rawDetections.filter { it.confidence >= minConfidence }        // Apply Non-Maximum Suppression.        val nmsFiltered = applyNms(filtered)        val elapsedMs = System.currentTimeMillis() - startTime        Timber.tag(TAG).d("Detection: ${rawDetections.size} raw → ${filtered.size} filtered → " +            "${nmsFiltered.size} after NMS (${elapsedMs}ms).")        nmsFiltered.sortedByDescending { it.confidence }    }    /**     * Apply Non-Maximum Suppression to remove overlapping boxes.     *     * Algorithm:     *  1. Sort by confidence descending.     *  2. Keep the highest-confidence box.     *  3. Remove all boxes with IoU > [nmsIoUThreshold] with the kept box.     *  4. Repeat for next-highest remaining box.     */    internal fun applyNms(objects: List<DetectedObject>): List<DetectedObject> {        if (objects.isEmpty()) return emptyList()        val sorted = objects.sortedByDescending { it.confidence }.toMutableList()        val kept = mutableListOf<DetectedObject>()        while (sorted.isNotEmpty()) {            val best = sorted.removeAt(0)            kept.add(best)            // Remove all boxes with IoU > threshold against the kept box.            // Only suppress boxes of the SAME class (don't suppress a person            // just because it overlaps with a car).            val toRemove = sorted.filter { other ->                other.classId == best.classId &&                    iou(best.boundingBox, other.boundingBox) > nmsIoUThreshold            }            sorted.removeAll(toRemove)        }        return kept    }    /**     * Compute Intersection over Union (IoU) of two bounding boxes.     *     * IoU = (intersection area) / (union area).     *     * Range: 0.0 (no overlap) → 1.0 (perfect overlap).     */    internal fun iou(a: BoundingBox, b: BoundingBox): Float {        val intersectionLeft = maxOf(a.left, b.left)        val intersectionTop = maxOf(a.top, b.top)        val intersectionRight = minOf(a.right, b.right)        val intersectionBottom = minOf(a.bottom, b.bottom)        val intersectionWidth = (intersectionRight - intersectionLeft).coerceAtLeast(0f)        val intersectionHeight = (intersectionBottom - intersectionTop).coerceAtLeast(0f)        val intersectionArea = intersectionWidth * intersectionHeight        val unionArea = a.area + b.area - intersectionArea        return if (unionArea > 0) intersectionArea / unionArea else 0f    }    /** True if the SSD model is loaded and ready. */    fun isReady(): Boolean = delegate.isReady()    /** Get the supported detection classes. */    fun supportedClasses(): List<DetectionClass> = delegate.supportedClasses()    private companion object {        private const val TAG = "ObjectDetector"        private const val DEFAULT_NMS_IOU_THRESHOLD = 0.45f        private const val DEFAULT_MIN_CONFIDENCE = 0.50f    }}// ──────────────────────────────────────────────────────────────────────────/** SSD model delegate interface — abstracts TFLite + NNAPI for testability. */interface SsdModelDelegate {    /** Detect objects in [frame]. Returns raw detections (pre-NMS). */    suspend fun detect(frame: RgbImage): List<DetectedObject>    /** True if the model is loaded and ready. */    fun isReady(): Boolean    /** Get the supported detection classes. */    fun supportedClasses(): List<DetectionClass>}